 pub fn resume_admission(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<bool,ValueError>{let state=slot.as_mut().ok_or_else(||invalid("original effect settlement is absent"))?;if !self.matches(state)||state.grant.is_none_or(|grant|grant.maximum_items==0||!semio_framework_value_control_contract::retained_clone_grant_admits(grant,state.demand))||!matches!(state.admission_phase,NativeEncodeEffectPostPhase::Waiting|NativeEncodeEffectPostPhase::Started){return Err(invalid("original work admission authority or phase changed"))}state.admission_phase=NativeEncodeEffectPostPhase::Started;match self.action.prepare_for_action(1,&mut state.work_action)?{None=>Ok(false),Some(true)=>{state.admission_phase=NativeEncodeEffectPostPhase::Completed;state.admitted=true;Ok(true)},Some(false)=>{state.admission_phase=NativeEncodeEffectPostPhase::Completed;Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original effect work is refused"))}}}
 /// ↩️ Cancels a matching reservation before the effect.
 pub fn recover_quote(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<bool,ValueError>{let state=slot.as_mut().ok_or_else(||invalid("original effect settlement is absent"))?;if !self.matches(state){return Err(invalid("original construction quote authority or phase changed"))}let port=self.construction.as_deref_mut().ok_or_else(||invalid("original construction source is absent"))?;if state.quote_phase==NativeEncodeEffectPostPhase::Completed&&state.physical_failure.is_some(){port.finish(&mut state.construction_action)?;let error=state.physical_failure.take().expect("original quote refusal retained");state.released=true;slot.take();return Err(error)}if state.quote_phase!=NativeEncodeEffectPostPhase::Started{return Err(invalid("original construction quote authority or phase changed"))}let action=state.construction_action.as_mut().ok_or_else(||invalid("original construction action is absent"))?;match port.recover_grant(action)?{None=>Ok(false),Some(Ok(grant))=>{state.grant=Some(grant);state.quote_phase=NativeEncodeEffectPostPhase::Completed;if grant.maximum_items==0||!semio_framework_value_control_contract::retained_clone_grant_admits(grant,state.demand){return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original effect quote is insufficient"))}Ok(true)},Some(Err(error))=>{state.physical_failure=Some(error);state.quote_phase=NativeEncodeEffectPostPhase::Completed;if let Err(finish)=port.finish(&mut state.construction_action){return Err(finish)}let error=state.physical_failure.take().expect("original quote refusal retained");state.released=true;slot.take();Err(error)}}}
 /// ↩️ Cancels a matching reservation before the effect.
  pub fn cancel(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<NativeEncodeEffectCancellation,ValueError>{let state=slot.as_mut().ok_or_else(||invalid("original effect settlement is absent"))?;if !self.matches(state)||state.progress.is_some()||!state.admitted||state.admission_phase!=NativeEncodeEffectPostPhase::Completed||state.work_phase!=NativeEncodeEffectPostPhase::Waiting||state.physical_phase!=NativeEncodeEffectPostPhase::Waiting{return Err(invalid("original effect cannot cancel its retained state"))}let identity=state.identity;let port=self.construction.as_deref_mut().ok_or_else(||invalid("original construction source is absent"))?;let action=state.construction_action.as_mut().ok_or_else(||invalid("original construction action is absent"))?;if matches!(action.phase(),semio_framework_value_control_contract::OriginalConstructionPhase::Fresh|semio_framework_value_control_contract::OriginalConstructionPhase::Granted){port.cancel(action,false,RetainedCloneProgress::default(),None)?}self.action.cancel_for_action(&mut state.work_action)?;port.finish(&mut state.construction_action)?;release_unstarted(slot);Ok(NativeEncodeEffectCancellation{identity})}
 /// ↩️ Releases a refused quote or admission before any action was reserved.
 pub fn release_refused(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<NativeEncodeEffectCancellation,ValueError>{let state=slot.as_mut().ok_or_else(||invalid("original effect settlement is absent"))?;if !self.matches(state)||state.quote_phase!=NativeEncodeEffectPostPhase::Completed||state.admitted||state.progress.is_some()||state.physical_failure.is_some()||state.admission_phase==NativeEncodeEffectPostPhase::Started{return Err(invalid("original refused effect is not settled"))}let identity=state.identity;let port=self.construction.as_deref_mut().ok_or_else(||invalid("original construction source is absent"))?;let action=state.construction_action.as_mut().ok_or_else(||invalid("original construction action is absent"))?;if matches!(action.phase(),semio_framework_value_control_contract::OriginalConstructionPhase::Fresh|semio_framework_value_control_contract::OriginalConstructionPhase::Granted){port.cancel(action,false,RetainedCloneProgress::default(),None)?}port.finish(&mut state.construction_action)?;release_unstarted(slot);Ok(NativeEncodeEffectCancellation{identity})}
 /// 🧾️ Posts each actual callback once using the exact original source loans.
 pub fn settle(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<bool,ValueError>{let state=slot.as_mut().ok_or_else(||invalid("original effect settlement is absent"))?;if !self.matches(state){return Err(invalid("original effect issuer changed"))}let progress=state.submitted_progress.ok_or_else(||invalid("original submitted effect progress is absent"))?;if state.grant.is_none(){return Err(invalid("original effect quote is absent"))}if state.work_phase!=NativeEncodeEffectPostPhase::Completed{return Ok(false)}let port=self.construction.as_deref_mut().ok_or_else(||invalid("original construction source is absent"))?;if state.physical_phase==NativeEncodeEffectPostPhase::Waiting{let action=state.construction_action.as_mut().ok_or_else(||invalid("original construction action is absent"))?;if state.performed==Some(false){port.cancel(action,false,progress,state.actual)?;state.physical_phase=NativeEncodeEffectPostPhase::Completed}else{state.physical_phase=NativeEncodeEffectPostPhase::Started;if let Err(error)=port.post(action,progress,state.actual){if action.phase()==semio_framework_value_control_contract::OriginalConstructionPhase::Granted{state.physical_phase=NativeEncodeEffectPostPhase::Waiting}return Err(error)}}}if state.physical_phase==NativeEncodeEffectPostPhase::Completed&&state.construction_action.is_some(){port.finish(&mut state.construction_action)?}if state.physical_phase==NativeEncodeEffectPostPhase::Started{let action=state.construction_action.as_mut().ok_or_else(||invalid("original construction action is absent"))?;if action.phase()==semio_framework_value_control_contract::OriginalConstructionPhase::AcceptStarted{let Some(reply)=port.recover_accept(action)?else{return Ok(false)};state.physical_failure=reply.err()}port.finish(&mut state.construction_action)?;state.physical_phase=NativeEncodeEffectPostPhase::Completed}if state.work_proof.is_some(){self.action.finish_for_action(&mut state.work_proof,&mut state.work_action)?}Ok(true)}

